import { test, expect } from '@playwright/test';

test.describe('Table Loading State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display loading state while data is being fetched', async ({ page }) => {
    // Set up intercept for table data API
    await page.route('**/api/table-data', (route) => {
      route.abort('API call timed out');
    });

    // Verify loading state is visible
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify table header is visible
    const tableHeader = page.getByRole('heading', { name: /table data/i });
    await expect(tableHeader).toBeVisible();

    // Verify table body is empty
    const tableBody = page.getByRole('region', { name: /table body/i });
    await expect(tableBody).toBeEmpty();

    // Verify loading message is displayed
    const loadingMessage = page.getByText(/data is being fetched/i);
    await expect(loadingMessage).toBeVisible();

    // Verify table is initially disabled
    const tableContainer = page.getByRole('region', { name: /table list/i });
    await expect(tableContainer).toBeDisabled();

    // Trigger data fetch
    const fetchButton = page.getByRole('button', { name: /fetch data/i });
    await fetchButton.click();

    // Wait for loading state to be visible
    await page.waitForTimeout(500);

    // Verify loading state disappears
    await expect(loadingIndicator).not.toBeVisible();

    // Verify table is now enabled
    await expect(tableContainer).not.toBeDisabled();

    // Verify table body is populated with data
    const tableRows = page.locator('[data-testid="table-row"]');
    await expect(tableRows).toHaveCount(3);

    // Verify table has data
    const tableData = page.getByText(/item 1/i);
    await expect(tableData).toBeVisible();

    // Verify table has pagination controls
    const pageControl = page.getByRole('button', { name: /page 1/i });
    await expect(pageControl).toBeVisible();

    // Verify table has sorting controls
    const sortControl = page.getByRole('button', { name: /sort by name/i });
    await expect(sortControl).toBeVisible();

    // Verify table has export button
    const exportButton = page.getByRole('button', { name: /export/i });
    await expect(exportButton).toBeVisible();

    // Verify export button is disabled initially
    await expect(exportButton).toBeDisabled();

    // Verify export button is enabled after data is loaded
    await expect(exportButton).not.toBeDisabled();
  });

  test('should handle API failure and display error state', async ({ page }) => {
    // Set up intercept for table data API with error response
    await page.route('**/api/table-data', (route) => {
      route.abort('API error');
    });

    // Verify loading state is visible
    const loadingIndicator = page.getByRole('status', { name: /loading/i });
    await expect(loadingIndicator).toBeVisible();

    // Verify table header is visible
    const tableHeader = page.getByRole('heading', { name: /table data/i });
    await expect(tableHeader).toBeVisible();

    // Verify table body is empty
    const tableBody = page.getByRole('region', { name: /table body/i });
    await expect(tableBody).toBeEmpty();

    // Verify loading message is displayed
    const loadingMessage = page.getByText(/data is being fetched/i);
    await expect(loadingMessage).toBeVisible();

    // Verify error state is displayed
    const errorMessage = page.getByText(/failed to load data/i);
    await expect(errorMessage).toBeVisible();

    // Verify table is initially disabled
    const tableContainer = page.getByRole('region', { name: /table list/i });
    await expect(tableContainer).toBeDisabled();

    // Trigger data fetch
    const fetchButton = page.getByRole('button', { name: /fetch data/i });
    await fetchButton.click();

    // Wait for error state to be visible
    await page.waitForTimeout(500);

    // Verify loading state disappears
    await expect(loadingIndicator).not.toBeVisible();

    // Verify error message is visible
    await expect(errorMessage).toBeVisible();

    // Verify table is still disabled
    await expect(tableContainer).toBeDisabled();

    // Verify error message contains retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify retry button is enabled
    await expect(retryButton).not.toBeDisabled();

    // Verify error message contains error code
    const errorCode = page.getByText(/500/i);
    await expect(errorCode).toBeVisible();

    // Verify error message contains user-friendly message
    const userMessage = page.getByText(/unable to load data at this time/i);
    await expect(userMessage).toBeVisible();

    // Verify export button is disabled due to error
    const exportButton = page.getByRole('button', { name: /export/i });
    await expect(exportButton).toBeDisabled();
  });
});
